#Область ОбменССервисом

// Отправляет запрос к LLM.
//
// Параметры:
//  Настройки - Структура - АдресСервиса, Токен, Модель, ТаймаутСек.
//  Сообщения - Массив - элементы Соответствие с ключами "role" и "content".
//
// Возвращаемое значение:
//  Структура - Успех (Булево), Текст (Строка), Ошибка (Строка).
//
Функция ОтправитьЗапрос(Настройки, Сообщения) Экспорт

	Результат = Новый Структура("Успех, Текст, Ошибка", Ложь, "", "");

	Попытка

		АдресСтруктура = РазобратьАдрес(Настройки.АдресСервиса);

		ЗащищенноеСоединение = Неопределено;
		Если АдресСтруктура.Защищенное Тогда
			ЗащищенноеСоединение = Новый ЗащищенноеСоединениеOpenSSL();
		КонецЕсли;

		Таймаут = ?(ЗначениеЗаполнено(Настройки.ТаймаутСек), Настройки.ТаймаутСек, ТаймаутПоУмолчанию());

		Соединение = Новый HTTPСоединение(
			АдресСтруктура.Хост,
			АдресСтруктура.Порт,
			,
			,
			,
			Таймаут,
			ЗащищенноеСоединение);

		HTTPЗапросСервису = Новый HTTPЗапрос(АдресСтруктура.Путь);
		HTTPЗапросСервису.Заголовки.Вставить("Content-Type", "application/json");
		HTTPЗапросСервису.Заголовки.Вставить("Accept", "application/json");
		Если ЗначениеЗаполнено(Настройки.Токен) Тогда
			HTTPЗапросСервису.Заголовки.Вставить("Authorization", "Bearer " + СокрЛП(Настройки.Токен));
			// Anthropic (Claude) дополнительно требует собственный заголовок с ключом и версией API.
			Если Найти(НРег(АдресСтруктура.Хост), "anthropic") > 0 Тогда
				HTTPЗапросСервису.Заголовки.Вставить("x-api-key", СокрЛП(Настройки.Токен));
				HTTPЗапросСервису.Заголовки.Вставить("anthropic-version", "2023-06-01");
			КонецЕсли;
		КонецЕсли;

		ТелоЗапроса = Новый Структура;
		ТелоЗапроса.Вставить("model", Настройки.Модель);
		ТелоЗапроса.Вставить("messages", Сообщения);
		ТелоЗапроса.Вставить("stream", Ложь);

		// Часть сервисов (в частности, Anthropic) требует явного ограничения длины ответа.
		МаксТокенов = 0;
		Настройки.Свойство("МаксТокенов", МаксТокенов);
		Если ЗначениеЗаполнено(МаксТокенов) Тогда
			ТелоЗапроса.Вставить("max_tokens", МаксТокенов);
		КонецЕсли;

		HTTPЗапросСервису.УстановитьТелоИзСтроки(
			ОбъектВJSON(ТелоЗапроса),
			КодировкаТекста.UTF8,
			ИспользованиеByteOrderMark.НеИспользовать);

		Ответ = Соединение.ВызватьHTTPМетод("POST", HTTPЗапросСервису);
		ТелоОтвета = Ответ.ПолучитьТелоКакСтроку(КодировкаТекста.UTF8);

		Если Ответ.КодСостояния >= 300 Тогда
			Результат.Ошибка = "HTTP " + Формат(Ответ.КодСостояния, "ЧГ=0") + ": " + ТелоОтвета;
			Возврат Результат;
		КонецЕсли;

		Данные = JSONВОбъект(ТелоОтвета);
		Текст = ИзвлечьТекстОтвета(Данные);

		Если ПустаяСтрока(Текст) Тогда
			Результат.Ошибка = "Сервис вернул пустой ответ. Тело ответа: " + Лев(ТелоОтвета, 2000);
			Возврат Результат;
		КонецЕсли;

		Результат.Текст = Текст;
		Результат.Успех = Истина;

	Исключение
		Результат.Ошибка = ОписаниеОшибки();
	КонецПопытки;

	Возврат Результат;

КонецФункции

// Формирует сообщение диалога для передачи сервису.
