Функция ОбъектВJSON(Значение) Экспорт

	Запись = Новый ЗаписьJSON;
	Запись.УстановитьСтроку();
	ЗаписатьJSON(Запись, Значение);
	Возврат Запись.Закрыть();

КонецФункции

Функция JSONВОбъект(Строка) Экспорт

	Если ПустаяСтрока(Строка) Тогда
		Возврат Неопределено;
	КонецЕсли;

	Чтение = Новый ЧтениеJSON;
	Чтение.УстановитьСтроку(Строка);
	Значение = ПрочитатьJSON(Чтение, Истина);
	Чтение.Закрыть();

	Возврат Значение;

КонецФункции

Функция РазобратьАдрес(Адрес)

	Стр = СокрЛП(Адрес);
	Защищенное = Ложь;

	Если Найти(НРег(Стр), "https://") = 1 Тогда
		Защищенное = Истина;
		Стр = Сред(Стр, 9);
	ИначеЕсли Найти(НРег(Стр), "http://") = 1 Тогда
		Стр = Сред(Стр, 8);
	КонецЕсли;

	ПозицияПути = Найти(Стр, "/");
	Если ПозицияПути = 0 Тогда
		ХостПорт = Стр;
		Путь = "/";
	Иначе
		ХостПорт = Лев(Стр, ПозицияПути - 1);
		Путь = Сред(Стр, ПозицияПути);
	КонецЕсли;

	Порт = ?(Защищенное, 443, 80);
	ПозицияПорта = Найти(ХостПорт, ":");
	Если ПозицияПорта > 0 Тогда
		Попытка
			Порт = Число(Сред(ХостПорт, ПозицияПорта + 1));
		Исключение
			Порт = ?(Защищенное, 443, 80);
		КонецПопытки;
		ХостПорт = Лев(ХостПорт, ПозицияПорта - 1);
	КонецЕсли;

	Возврат Новый Структура("Хост, Порт, Путь, Защищенное", ХостПорт, Порт, Путь, Защищенное);

КонецФункции

Функция ИзвлечьТекстОтвета(Данные)

	Если ТипЗнч(Данные) <> Тип("Соответствие") Тогда
		Возврат "";
	КонецЕсли;

	Выборы = Данные.Получить("choices");
	Если ТипЗнч(Выборы) = Тип("Массив") И Выборы.Количество() > 0 Тогда

		Первый = Выборы[0];
		Если ТипЗнч(Первый) = Тип("Соответствие") Тогда

			Сообщение = Первый.Получить("message");
			Если ТипЗнч(Сообщение) = Тип("Соответствие") Тогда
				Содержимое = Сообщение.Получить("content");
				Если Содержимое <> Неопределено Тогда
					Возврат Строка(Содержимое);
				КонецЕсли;
			КонецЕсли;

			Если Первый.Получить("text") <> Неопределено Тогда
				Возврат Строка(Первый.Получить("text"));
			КонецЕсли;

		КонецЕсли;

	КонецЕсли;

	Ошибка = Данные.Получить("error");
	Если Ошибка <> Неопределено Тогда
		Если ТипЗнч(Ошибка) = Тип("Соответствие") И Ошибка.Получить("message") <> Неопределено Тогда
			Возврат "Сервис вернул ошибку: " + Строка(Ошибка.Получить("message"));
		КонецЕсли;
		Возврат "Сервис вернул ошибку: " + Строка(Ошибка);
	КонецЕсли;

	Возврат "";

КонецФункции

