#Область ВременнаяИБ

// Подключается к временной ИБ через внешнее COM-соединение.
//
// Параметры:
//  СтрокаПодключения - Строка - строка соединения (File=...; или Srvr=...;Ref=...;).
//  Пользователь      - Строка - имя пользователя (необязательно, если указано в строке).
//  Пароль            - Строка - пароль пользователя (необязательно).
//
// Возвращаемое значение:
//  Структура - Успех (Булево), Приложение (COM-объект), Ошибка (Строка).
//
Функция ПодключитьВременнуюИБ(СтрокаПодключения, Пользователь = "", Пароль = "") Экспорт

	Результат = Новый Структура("Успех, Приложение, Ошибка", Ложь, Неопределено, "");

	Попытка

		Если ПустаяСтрока(СтрокаПодключения) Тогда
			Результат.Ошибка = "Не указана строка подключения временной ИБ.";
			Возврат Результат;
		КонецЕсли;

		СтрокаСоединения = СокрЛП(СтрокаПодключения);

		Если ЗначениеЗаполнено(Пользователь) И Найти(НРег(СтрокаСоединения), "usr=") = 0 Тогда
			Если Не СтрЗаканчиваетсяНа(СтрокаСоединения, ";") Тогда
				СтрокаСоединения = СтрокаСоединения + ";";
			КонецЕсли;
			СтрокаСоединения = СтрокаСоединения + "Usr=""" + Пользователь + """;";
			Если ЗначениеЗаполнено(Пароль) Тогда
				СтрокаСоединения = СтрокаСоединения + "Pwd=""" + Пароль + """;";
			КонецЕсли;
		КонецЕсли;

		Коннектор = Новый COMОбъект("V83.COMConnector");
		Результат.Приложение = Коннектор.Connect(СтрокаСоединения);
		Результат.Успех = Истина;

	Исключение
		Результат.Ошибка = ОписаниеОшибки();
	КонецПопытки;

	Возврат Результат;

КонецФункции

// Проверка, оканчивается ли строка указанной подстрокой (для строк без учёта регистра не требуется здесь).
