// Загружает конфигурацию из файлов в подключённую временную ИБ и обновляет её структуру.
//
// Параметры:
//  Приложение     - COM-объект, полученный от ПодключитьВременнуюИБ.
//  КаталогСтруктуры - Строка - путь к каталогу с выгруженной конфигурацией (файлами).
//
// Возвращаемое значение:
//  Структура - Успех (Булево), Ошибка (Строка).
//
Функция ЗагрузитьСтруктуруКонфигурации(Приложение, КаталогСтруктуры) Экспорт

	Результат = Новый Структура("Успех, Ошибка", Ложь, "");

	Попытка

		Если Приложение = Неопределено Тогда
			Результат.Ошибка = "Соединение с временной ИБ не установлено.";
			Возврат Результат;
		КонецЕсли;

		Если ПустаяСтрока(КаталогСтруктуры) Тогда
			Результат.Ошибка = "Не указан каталог структуры временной базы данных.";
			Возврат Результат;
		КонецЕсли;

		Приложение.ЗагрузитьКонфигурациюИзФайлов(КаталогСтруктуры);
		Приложение.ОбновитьИнформационнуюБазуКонфигурации();

		Результат.Успех = Истина;

	Исключение
		Результат.Ошибка = ОписаниеОшибки();
	КонецПопытки;

	Возврат Результат;

КонецФункции

// Формирует текстовое описание состава метаданных подключённой временной ИБ
// для передачи модели как контекста реальной структуры базы (через COM).
Функция ПолучитьОписаниеМетаданных(Приложение) Экспорт

	Если Приложение = Неопределено Тогда
		Возврат "";
	КонецЕсли;

	Попытка
		МетаданныеПриложения = Приложение.Метаданные;
	Исключение
		Возврат "Не удалось получить метаданные временной ИБ: " + ОписаниеОшибки();
	КонецПопытки;

	Возврат СобратьОписаниеМетаданных(МетаданныеПриложения);

КонецФункции

// Формирует текстовое описание метаданных ТЕКУЩЕЙ базы (в которой запущена обработка).
// COM не используется: берётся глобальный объект Метаданные текущего сеанса.
// Используется для контекста LLM и отпечатка конфигурации в базе знаний Git.
Функция ПолучитьОписаниеМетаданныхТекущейБазы() Экспорт

	Попытка
		Возврат СобратьОписаниеМетаданных(Метаданные);
	Исключение
		Возврат "Не удалось получить метаданные текущей базы: " + ОписаниеОшибки();
	КонецПопытки;

КонецФункции

// Общий сборщик текстового описания по объекту метаданных (текущая база или COM).
Функция СобратьОписаниеМетаданных(ОбъектМетаданных)

	Текст = "";

	Попытка
		Текст = Текст + "Конфигурация: " + Строка(ОбъектМетаданных.Синоним) + Символы.ПС;
	Исключение
		// Синоним конфигурации может быть недоступен - не критично.
		Текст = Текст + "";
	КонецПопытки;

	Текст = Текст + ОписаниеКоллекцииМетаданных(ОбъектМетаданных.Справочники, "Справочники");
	Текст = Текст + ОписаниеКоллекцииМетаданных(ОбъектМетаданных.Документы, "Документы");
	Текст = Текст + ОписаниеКоллекцииМетаданных(ОбъектМетаданных.РегистрыСведений, "Регистры сведений");
	Текст = Текст + ОписаниеКоллекцииМетаданных(ОбъектМетаданных.РегистрыНакопления, "Регистры накопления");
	Текст = Текст + ОписаниеКоллекцииМетаданных(ОбъектМетаданных.Перечисления, "Перечисления");
	Текст = Текст + ОписаниеКоллекцииМетаданных(ОбъектМетаданных.Обработки, "Обработки");
	Текст = Текст + ОписаниеКоллекцииМетаданных(ОбъектМетаданных.Отчеты, "Отчеты");
	Текст = Текст + ОписаниеКоллекцииМетаданных(ОбъектМетаданных.ПланыВидовХарактеристик, "Планы видов характеристик");
	Текст = Текст + ОписаниеКоллекцииМетаданных(ОбъектМетаданных.РегистрыБухгалтерии, "Регистры бухгалтерии");

	Возврат Текст;

КонецФункции


Функция ОписаниеКоллекцииМетаданных(Коллекция, Заголовок)

	Попытка
		Если Коллекция = Неопределено Или Коллекция.Количество() = 0 Тогда
			Возврат "";
		КонецЕсли;
	Исключение
		Возврат "";
	КонецПопытки;

	Текст = Заголовок + ":" + Символы.ПС;

	Попытка
		Для Каждого Объект Из Коллекция Цикл
			Текст = Текст + "- " + Строка(Объект.Имя);
			СтрокаРеквизитов = ОписаниеРеквизитов(Объект);
			Если Не ПустаяСтрока(СтрокаРеквизитов) Тогда
				Текст = Текст + " (" + СтрокаРеквизитов + ")";
			КонецЕсли;
			Текст = Текст + Символы.ПС;
		КонецЦикла;
	Исключение
		Текст = Текст + "  (не удалось перечислить объекты: " + ОписаниеОшибки() + ")" + Символы.ПС;
	КонецПопытки;

	Возврат Текст;

КонецФункции

Функция ОписаниеРеквизитов(Объект)

	Результат = "";

	Попытка
		Реквизиты = Объект.Реквизиты;
		Если Реквизиты = Неопределено Тогда
			Возврат "";
		КонецЕсли;
		Для Каждого Реквизит Из Реквизиты Цикл
			Если Не ПустаяСтрока(Результат) Тогда
				Результат = Результат + ", ";
			КонецЕсли;
			Результат = Результат + Строка(Реквизит.Имя);
		КонецЦикла;
	Исключение
		Возврат "";
	КонецПопытки;

	Возврат Результат;

КонецФункции

#КонецОбласти

// ============================================================================================
// ВАЖНО ДЛЯ ЛЮБОГО АГЕНТА/РАЗРАБОТЧИКА, ЧИТАЮЩЕГО ЭТОТ КОД:
//
// В этой обработке существуют ДВЕ РАЗНЫЕ базы, и их нельзя путать:
//
// 1) "ТЕКУЩАЯ БАЗА" - это база, в которой запущена САМА ЭТА ОБРАБОТКА (тот сеанс 1С,
//    в котором сейчас исполняется данный код). Для работы с текущей базой COM-СОЕДИНЕНИЕ
//    НЕ ИСПОЛЬЗУЕТСЯ И НЕ ТРЕБУЕТСЯ - весь код (см. область "ТекущаяБаза" ниже) выполняется
//    напрямую встроенным языком в контексте текущего сеанса/сервера. Строка подключения этой
//    базы получается функцией СтрокаСоединенияИнформационнойБазы(), а выгрузка её структуры -
//    штатной глобальной процедурой ВыгрузитьКонфигурациюВФайлы(), без каких-либо внешних
//    объектов.
//
// 2) "ВРЕМЕННАЯ ИБ" (см. область "ВременнаяИБ" выше) - это ОТДЕЛЬНАЯ, ДРУГАЯ база (обычно
//    файловая, создаваемая отдельно), к которой обработка подключается ИЗВНЕ через COM
//    (Новый COMОбъект("V83.COMConnector")). Именно во временную ИБ загружается (через COM)
//    структура/код, изменённые по заданию оператора, из каталога КаталогСтруктурыВременнойБазыДанных -
//    это песочница для проверки, ОТДЕЛЬНАЯ от текущей рабочей базы.
//
// Никогда не используйте COM для работы с текущей базой - это не нужно и является ошибкой.
// ============================================================================================

#Область ТекущаяБаза

// Возвращает строку соединения ТЕКУЩЕЙ базы - той, в которой выполняется сама обработка.
// COM здесь НЕ используется: значение получается напрямую встроенной функцией платформы.
Функция ПолучитьСтрокуПодключенияТекущейБазы() Экспорт

	Возврат СтрокаСоединенияИнформационнойБазы();

КонецФункции

// Выгружает структуру конфигурации ТЕКУЩЕЙ базы (в которой выполняется сама обработка)
// в XML-файлы в указанный каталог. COM-соединение НЕ используется - процедура выполняется
// прямо в текущем сеансе/сервере (требуются права на административные функции).
//
// Параметры:
//  Каталог - Строка - путь к каталогу, куда будет выгружена структура конфигурации.
//
// Возвращаемое значение:
//  Структура - Успех (Булево), Ошибка (Строка).
//
Функция ВыгрузитьСтруктуруТекущейБазы(Каталог) Экспорт

	Результат = Новый Структура("Успех, Ошибка", Ложь, "");

	Попытка

		Если ПустаяСтрока(Каталог) Тогда
			Результат.Ошибка = "Не указан каталог структуры текущей базы.";
			Возврат Результат;
		КонецЕсли;

		// Прямой вызов штатной глобальной процедуры платформы - выполняется в текущем сеансе,
		// без COM и без внешнего соединения (поскольку мы уже находимся в нужной базе).
		//ВыгрузитьКонфигурациюВФайлы(Каталог);

		Результат.Успех = Истина;

	Исключение
		Результат.Ошибка = ОписаниеОшибки();
	КонецПопытки;

	Возврат Результат;

КонецФункции

#КонецОбласти

#Область БазаЗнанийGit

// Вычисляет короткий стабильный отпечаток (по MD5) от текста описания метаданных -
// используется как ключ привязки записей знаний к конкретной конфигурации.
Функция ВычислитьОтпечаток(Текст) Экспорт

	Если ПустаяСтрока(Текст) Тогда
		Возврат "";
	КонецЕсли;

	ХешДанные = Новый ХешированиеДанных(ХешФункция.MD5);
	ХешДанные.Добавить(Текст);

	Отпечаток = Base64Строка(ХешДанные.ХешСумма);
	Отпечаток = СтрЗаменить(Отпечаток, "+", "-");
	Отпечаток = СтрЗаменить(Отпечаток, "/", "_");
	Отпечаток = СтрЗаменить(Отпечаток, "=", "");

	Возврат Отпечаток;

КонецФункции

// Кодирует произвольную текстовую строку (UTF-8) в Base64.
Функция СтрокаВBase64(Строка) Экспорт

	Поток = Новый ПотокВПамяти;
	Записать = Новый ЗаписьТекста(Поток, КодировкаТекста.UTF8, , Ложь);
	Записать.ЗаписатьСтроку(Строка);
	Записать.Закрыть();

	Возврат Base64Строка(Поток.ЗакрытьИПолучитьДвоичныеДанные());

КонецФункции

// Декодирует Base64-строку (UTF-8) обратно в текст.
Функция Base64ВСтроку(Строка) Экспорт

	Если ПустаяСтрока(Строка) Тогда
		Возврат "";
	КонецЕсли;

	ДвДанные = Base64Значение(Строка);
	Поток = ДвДанные.ОткрытьПотокДляЧтения();
	Чтение = Новый ЧтениеТекста(Поток, КодировкаТекста.UTF8);
	Результат = Чтение.ПрочитатьВсе();
	Чтение.Закрыть();

	Возврат Результат;

КонецФункции

// Выполняет запрос к REST API хостинга Git (по умолчанию - GitHub Contents API).
//
// Параметры:
//  Настройки - Структура - АдресGitAPI, ТокенGit.
//  Метод     - Строка - "GET", "PUT" и т.п.
//  Путь      - Строка - путь запроса относительно АдресGitAPI, начинается с "/".
//  ТелоJSON  - Структура, Неопределено - тело запроса (будет сериализовано в JSON).
//
// Возвращаемое значение:
//  Структура - Успех (Булево), Данные (десериализованный JSON или Неопределено), КодСостояния (Число), Ошибка (Строка).
//
Функция ЗапросGitHub(Настройки, Метод, Путь, ТелоJSON = Неопределено) Экспорт

	Результат = Новый Структура("Успех, Данные, КодСостояния, Ошибка", Ложь, Неопределено, 0, "");

	Попытка

		АдресБазовый = СокрЛП(Настройки.АдресGitAPI);
		Если ПустаяСтрока(АдресБазовый) Тогда
			АдресБазовый = "https://api.github.com";
		КонецЕсли;

		АдресСтруктура = РазобратьАдрес(АдресБазовый + Путь);

		ЗащищенноеСоединение = Неопределено;
		Если АдресСтруктура.Защищенное Тогда
			ЗащищенноеСоединение = Новый ЗащищенноеСоединениеOpenSSL();
		КонецЕсли;

		Соединение = Новый HTTPСоединение(
			АдресСтруктура.Хост,
			АдресСтруктура.Порт,
			,
			,
			,
			60,
			ЗащищенноеСоединение);

		HTTPЗапрос = Новый HTTPЗапрос(АдресСтруктура.Путь);
		HTTPЗапрос.Заголовки.Вставить("Accept", "application/vnd.github+json");
		HTTPЗапрос.Заголовки.Вставить("User-Agent", "1C-ExtCntrl-Agent");
		Если ЗначениеЗаполнено(Настройки.ТокенGit) Тогда
			HTTPЗапрос.Заголовки.Вставить("Authorization", "Bearer " + СокрЛП(Настройки.ТокенGit));
		КонецЕсли;

		Если ТелоJSON <> Неопределено Тогда
			HTTPЗапрос.УстановитьТелоИзСтроки(
				ОбъектВJSON(ТелоJSON),
				КодировкаТекста.UTF8,
				ИспользованиеByteOrderMark.НеИспользовать);
		КонецЕсли;

		Ответ = Соединение.ВызватьHTTPМетод(Метод, HTTPЗапрос);
		ТелоОтвета = Ответ.ПолучитьТелоКакСтроку(КодировкаТекста.UTF8);

		Результат.КодСостояния = Ответ.КодСостояния;

		Если Ответ.КодСостояния >= 300 Тогда
			Результат.Ошибка = "HTTP " + Формат(Ответ.КодСостояния, "ЧГ=0") + ": " + ТелоОтвета;
			Возврат Результат;
		КонецЕсли;

		Если Не ПустаяСтрока(ТелоОтвета) Тогда
			Результат.Данные = JSONВОбъект(ТелоОтвета);
		КонецЕсли;

		Результат.Успех = Истина;

	Исключение
		Результат.Ошибка = ОписаниеОшибки();
	КонецПопытки;

	Возврат Результат;

КонецФункции

// Сохраняет запись знания (задание/код/результат) в репозиторий Git отдельным файлом.
//
// Параметры:
//  Настройки        - Структура - РепозиторийGit, ВеткаGit, ТокенGit, КаталогБазыЗнанийGit, АдресGitAPI.
//  Отпечаток        - Строка - отпечаток конфигурации (см. ВычислитьОтпечаток).
//  Задание          - Строка.
//  Код              - Строка.
//  Язык             - Строка.
//  РезультатВыполнения - Строка.
//  Успешно          - Булево.
//  ТипЗаписи        - Строка - "code" (результат выполнения кода) или "note" (урок из диалога).
//
// Возвращаемое значение:
//  Структура - Успех (Булево), Ошибка (Строка).
//
Функция СохранитьЗнание(Настройки, Отпечаток, Задание, Код, Язык, РезультатВыполнения, Успешно, ТипЗаписи = "code") Экспорт


	РезультатОперации = Новый Структура("Успех, Ошибка", Ложь, "");

	Если ПустаяСтрока(Настройки.РепозиторийGit) Или ПустаяСтрока(Настройки.ТокенGit) Или ПустаяСтрока(Отпечаток) Тогда
		РезультатОперации.Ошибка = "Не заданы параметры подключения к базе знаний Git.";
		Возврат РезультатОперации;
	КонецЕсли;

	Попытка

		Каталог = ?(ПустаяСтрока(Настройки.КаталогБазыЗнанийGit), "knowledge", СокрЛП(Настройки.КаталогБазыЗнанийGit));
		Ветка = ?(ПустаяСтрока(Настройки.ВеткаGit), "main", СокрЛП(Настройки.ВеткаGit));

		Запись = Новый Структура;
		Запись.Вставить("fingerprint", Отпечаток);
		Запись.Вставить("task", Задание);
		Запись.Вставить("code", Код);
		Запись.Вставить("lang", Язык);
		Запись.Вставить("result", РезультатВыполнения);
		Запись.Вставить("success", Успешно);
		Запись.Вставить("type", ?(ПустаяСтрока(ТипЗаписи), "code", ТипЗаписи));
		Запись.Вставить("timestamp", ТекущаяДатаСеанса());


		ИмяФайла = Формат(ТекущаяДатаСеанса(), "ГГГГММДДЧЧММСС")
			+ "_" + СтрЗаменить(Строка(Новый УникальныйИдентификатор), "-", "")
			+ ".json";

		Путь = Каталог + "/" + Отпечаток + "/" + ИмяФайла;

		ТелоЗапроса = Новый Структура;
		ТелоЗапроса.Вставить("message", "knowledge: " + Отпечаток + " " + ИмяФайла);
		ДвоичныеДанные = ПолучитьДвоичныеДанныеИзСтроки(ОбъектВJSON(Запись), КодировкаТекста.UTF8, Ложь);
		РезультатBase64 = Base64Строка(ДвоичныеДанные);
		РезультатBase64 = СтрЗаменить(РезультатBase64, Символы.ПС, "");
		РезультатBase64 = СтрЗаменить(РезультатBase64, Символы.ВК, "");
		ТелоЗапроса.Вставить("content", РезультатBase64);
		ТелоЗапроса.Вставить("branch", Ветка);

		ПутьAPI = "/repos/" + СокрЛП(Настройки.РепозиторийGit) + "/contents/" + Путь;

		Ответ = ЗапросGitHub(Настройки, "PUT", ПутьAPI, ТелоЗапроса);

		Если Не Ответ.Успех Тогда
			РезультатОперации.Ошибка = Ответ.Ошибка;
			Возврат РезультатОперации;
		КонецЕсли;

		РезультатОперации.Успех = Истина;

	Исключение
		РезультатОперации.Ошибка = ОписаниеОшибки();
	КонецПопытки;

	Возврат РезультатОперации;

КонецФункции

// Загружает текстовое представление последних N записей знаний для указанного отпечатка конфигурации,
// пригодное для подмешивания в системный промпт перед запросом к LLM.
//
// Параметры:
//  Настройки       - Структура - см. СохранитьЗнание.
//  Отпечаток       - Строка.
//  КоличествоЗаписей - Число.
//
// Возвращаемое значение:
//  Строка - текст с накопленными знаниями (пустая строка, если знаний нет или база знаний не настроена).
//
Функция ЗагрузитьЗнания(Настройки, Отпечаток, КоличествоЗаписей = 10) Экспорт


	Если ПустаяСтрока(Настройки.РепозиторийGit) Или ПустаяСтрока(Отпечаток) Тогда
		Возврат "";
	КонецЕсли;

	Попытка

		Каталог = ?(ПустаяСтрока(Настройки.КаталогБазыЗнанийGit), "knowledge", СокрЛП(Настройки.КаталогБазыЗнанийGit));
		Ветка = ?(ПустаяСтрока(Настройки.ВеткаGit), "main", СокрЛП(Настройки.ВеткаGit));

		ПутьAPI = "/repos/" + СокрЛП(Настройки.РепозиторийGit) + "/contents/" + Каталог + "/" + Отпечаток + "?ref=" + Ветка;

		Список = ЗапросGitHub(Настройки, "GET", ПутьAPI);

		Если Не Список.Успех Или ТипЗнч(Список.Данные) <> Тип("Массив") Тогда
			Возврат "";
		КонецЕсли;

		ИменаФайлов = Новый Массив;
		Для Каждого Файл Из Список.Данные Цикл
			Если ТипЗнч(Файл) = Тип("Соответствие") И Строка(Файл.Получить("type")) = "file" Тогда
				ИменаФайлов.Добавить(Строка(Файл.Получить("name")));
			КонецЕсли;
		КонецЦикла;

		ИменаФайлов.Сортировать();

		НачальныйИндекс = Макс(0, ИменаФайлов.Количество() - КоличествоЗаписей);

		ТекстУроков = "";
		ТекстРешений = "";

		Для Инд = НачальныйИндекс По ИменаФайлов.Количество() - 1 Цикл


			ИмяФайла = ИменаФайлов[Инд];
			ПутьФайлаAPI = "/repos/" + СокрЛП(Настройки.РепозиторийGit) + "/contents/" + Каталог + "/" + Отпечаток + "/" + ИмяФайла + "?ref=" + Ветка;

			ОтветФайл = ЗапросGitHub(Настройки, "GET", ПутьФайлаAPI);
			Если Не ОтветФайл.Успех Или ОтветФайл.Данные = Неопределено Тогда
				Продолжить;
			КонецЕсли;

			СодержимоеBase64 = Строка(ОтветФайл.Данные.Получить("content"));
			Если ПустаяСтрока(СодержимоеBase64) Тогда
				Продолжить;
			КонецЕсли;

			Запись = JSONВОбъект(Base64ВСтроку(СодержимоеBase64));

			Если ТипЗнч(Запись) = Тип("Соответствие") Тогда

				ТипЗаписи = Строка(Запись.Получить("type"));

				Если ТипЗаписи = "note" Тогда
					// Урок из диалога: короткая переиспользуемая формулировка.
					ТекстУроков = ТекстУроков + "- " + Строка(Запись.Получить("result")) + Символы.ПС;
				Иначе
					ТекстРешений = ТекстРешений + "- Задание: " + Строка(Запись.Получить("task")) + Символы.ПС;
					ТекстРешений = ТекстРешений + "  Код: " + Строка(Запись.Получить("code")) + Символы.ПС;
					ТекстРешений = ТекстРешений + "  Итог: " + Строка(Запись.Получить("result")) + Символы.ПС;
				КонецЕсли;

			КонецЕсли;

		КонецЦикла;

		// Уроки идут первыми: они компактнее и важнее для предотвращения повторных ошибок.
		ТекстЗнаний = "";

		Если Не ПустаяСтрока(ТекстУроков) Тогда
			ТекстЗнаний = ТекстЗнаний + "УРОКИ (не нарушай их):" + Символы.ПС + ТекстУроков + Символы.ПС;
		КонецЕсли;

		Если Не ПустаяСтрока(ТекстРешений) Тогда
			ТекстЗнаний = ТекстЗнаний + "ПРОШЛЫЕ РЕШЕНИЯ:" + Символы.ПС + ТекстРешений;
		КонецЕсли;

		Возврат ТекстЗнаний;


	Исключение
		Возврат "";
	КонецПопытки;

КонецФункции

