#Область РазборОтвета

// Разбирает текст ответа модели на последовательность блоков.
//
// Возвращаемое значение:
//  Массив - структуры с полями Вид ("текст" / "код"), Текст, Язык.
//
Функция РазобратьТекстНаБлоки(Текст) Экспорт

	Блоки = Новый Массив;
	Остаток = Текст;

	Пока Истина Цикл

		ПозицияОткрытия = Найти(Остаток, "```");

		Если ПозицияОткрытия = 0 Тогда
			Если Не ПустаяСтрока(Остаток) Тогда
				Блоки.Добавить(НовыйБлок("текст", Остаток, ""));
			КонецЕсли;
			Прервать;
		КонецЕсли;

		Префикс = Лев(Остаток, ПозицияОткрытия - 1);
		Если Не ПустаяСтрока(Префикс) Тогда
			Блоки.Добавить(НовыйБлок("текст", Префикс, ""));
		КонецЕсли;

		Остаток = Сред(Остаток, ПозицияОткрытия + 3);

		Язык = "";
		ПозицияПереноса = Найти(Остаток, Символы.ПС);
		Если ПозицияПереноса > 0 Тогда
			ВозможныйЯзык = СокрЛП(СтрЗаменить(Лев(Остаток, ПозицияПереноса - 1), Символы.ВК, ""));
			Если СтрДлина(ВозможныйЯзык) <= 20 Тогда
				Язык = ВозможныйЯзык;
				Остаток = Сред(Остаток, ПозицияПереноса + 1);
			КонецЕсли;
		КонецЕсли;

		ПозицияЗакрытия = Найти(Остаток, "```");
		Если ПозицияЗакрытия = 0 Тогда
			Блоки.Добавить(НовыйБлок("код", Остаток, Язык));
			Прервать;
		КонецЕсли;

		Блоки.Добавить(НовыйБлок("код", Лев(Остаток, ПозицияЗакрытия - 1), Язык));
		Остаток = Сред(Остаток, ПозицияЗакрытия + 3);

	КонецЦикла;

	Возврат Блоки;

КонецФункции

Функция НовыйБлок(Вид, Текст, Язык)

	Возврат Новый Структура("Вид, Текст, Язык", Вид, СокрП(Текст), Язык);

КонецФункции

// Маркер, которым модель помечает урок, подлежащий сохранению в базу знаний.
Функция МаркерЗаметки() Экспорт

	Возврат "[ЗАПОМНИТЬ:";

КонецФункции

// Извлекает из ответа модели все уроки, помеченные маркером [ЗАПОМНИТЬ: ...].
//
// Возвращаемое значение:
//  Массив - строки с текстами уроков (без маркера).
//
Функция ИзвлечьЗаметки(Текст) Экспорт

	Заметки = Новый Массив;

	Если ПустаяСтрока(Текст) Тогда
		Возврат Заметки;
	КонецЕсли;

	Маркер = МаркерЗаметки();
	Остаток = Текст;

	Пока Истина Цикл

		ПозицияНачала = Найти(Остаток, Маркер);
		Если ПозицияНачала = 0 Тогда
			Прервать;
		КонецЕсли;

		Остаток = Сред(Остаток, ПозицияНачала + СтрДлина(Маркер));

		ПозицияКонца = Найти(Остаток, "]");
		Если ПозицияКонца = 0 Тогда
			Прервать;
		КонецЕсли;

		Заметка = СокрЛП(Лев(Остаток, ПозицияКонца - 1));
		Если Не ПустаяСтрока(Заметка) Тогда
			Заметки.Добавить(Заметка);
		КонецЕсли;

		Остаток = Сред(Остаток, ПозицияКонца + 1);

	КонецЦикла;

	Возврат Заметки;

КонецФункции

// Удаляет из ответа модели служебные маркеры [ЗАПОМНИТЬ: ...],
// чтобы оператор видел только содержательную часть ответа.
Функция УдалитьМаркерыЗаметок(Текст) Экспорт

	Если ПустаяСтрока(Текст) Тогда
		Возврат Текст;
	КонецЕсли;

	Маркер = МаркерЗаметки();
	Результат = "";
	Остаток = Текст;

	Пока Истина Цикл

		ПозицияНачала = Найти(Остаток, Маркер);
		Если ПозицияНачала = 0 Тогда
			Результат = Результат + Остаток;
			Прервать;
		КонецЕсли;

		Результат = Результат + Лев(Остаток, ПозицияНачала - 1);
		Остаток = Сред(Остаток, ПозицияНачала + СтрДлина(Маркер));

		ПозицияКонца = Найти(Остаток, "]");
		Если ПозицияКонца = 0 Тогда
			Прервать;
		КонецЕсли;

		Остаток = Сред(Остаток, ПозицияКонца + 1);

	КонецЦикла;

	Возврат СокрП(Результат);

КонецФункции


