// Фрейм со сгенерированным кодом и кнопками подтверждения.
Функция HTMLБлокКода(Индекс, Код, Язык) Экспорт

	НомерСтр = Формат(Индекс, "ЧГ=0");
	ЯзыкПредставление = ?(ПустаяСтрока(Язык), "bsl", Язык);

	HTML = "<div class='codebox' id='code" + НомерСтр + "'>";
	HTML = HTML + "<div class='codehdr'>Сгенерированный код (" + ЭкранироватьHTML(ЯзыкПредставление) + ") &#8470;" + НомерСтр + "</div>";
	HTML = HTML + "<pre class='code'>" + ЭкранироватьHTML(Код) + "</pre>";
	HTML = HTML + "<div class='btns'>";
	HTML = HTML + "<a class='btn run' href='v8cmd:run:" + НомерСтр + "'>&#10004; Выполнить</a>";
	HTML = HTML + "<a class='btn rej' href='v8cmd:reject:" + НомерСтр + "'>&#10006; Отклонить</a>";
	HTML = HTML + "</div></div>";

	Возврат HTML;

