		+ ТекстВHTML(Текст) + "</div></div>";

КонецФункции

Функция ЭкранироватьHTML(Текст) Экспорт

	Результат = СтрЗаменить(Текст, "&", "&amp;");
	Результат = СтрЗаменить(Результат, "<", "&lt;");
	Результат = СтрЗаменить(Результат, ">", "&gt;");
	Результат = СтрЗаменить(Результат, """", "&quot;");
	Возврат Результат;

КонецФункции

Функция ТекстВHTML(Текст) Экспорт

	Результат = ЭкранироватьHTML(Текст);
	Результат = СтрЗаменить(Результат, Символы.ВК, "");
	Результат = СтрЗаменить(Результат, Символы.ПС, "<br>");
	Возврат Результат;

