	С = С + ".err {background: #fdeeee; border: 1px solid #f0b8b8; color: #8b1a1a;}";
	С = С + ".text {margin: 2px 0;}";
	С = С + ".codebox {border: 2px solid #2f7d32; border-radius: 6px; margin: 8px 0; background: #f4fbf4;}";
