	С = С + "pre.code {margin: 0; padding: 8px; font-family: Consolas, Courier New, monospace; font-size: 12px; white-space: pre-wrap; word-wrap: break-word; background: #ffffff;}";
	С = С + ".btns {padding: 6px 8px; border-top: 1px solid #cfe6cf;}";
	С = С + ".btn {display: inline-block; padding: 3px 12px; margin-right: 8px; border-radius: 4px; text-decoration: none; font-weight: bold; font-size: 12px; border: 1px solid #999999;}";
	С = С + ".run {background: #2f7d32; color: #ffffff; border-color: #24601f;}";
