	Если Не ПустаяСтрока(ЭтотОбъект.Объект.КаталогСтруктурыТекущейБазы) Тогда
		Диалог.Каталог = ЭтотОбъект.Объект.КаталогСтруктурыТекущейБазы;
	КонецЕсли;

	Если Диалог.Выбрать() Тогда
		ЭтотОбъект.Объект.КаталогСтруктурыТекущейБазы = Диалог.Каталог;
	КонецЕсли;

КонецПроцедуры

// Переключение режима агента выполняется ТОЛЬКО оператором вручную.
// При установке флажка автоматически отправляется запрос кода по согласованному плану.
&НаКлиенте
Процедура ПолеРежимActПриИзменении(Элемент)

	РежимActПриИзмененииСервер();

КонецПроцедуры

#КонецОбласти


#Область ОбработкаКомандДокумента

&НаКлиенте
Функция ИзвлечьКомандуИзСобытия(ДанныеСобытия)

	Ссылка = "";

	// Разные версии платформы и браузерных движков по-разному отдают данные события,
	// поэтому пробуем несколько вариантов получения адреса ссылки.
	Попытка
		Если ДанныеСобытия <> Неопределено Тогда
			Ссылка = Строка(ДанныеСобытия.Href);
		КонецЕсли;
	Исключение
		Ссылка = "";
	КонецПопытки;

	Если ПустаяСтрока(Ссылка) Тогда
		Попытка
			ЭлементДокумента = ДанныеСобытия.Element;
			Пока ЭлементДокумента <> Неопределено Цикл
				Попытка
					Ссылка = Строка(ЭлементДокумента.href);
				Исключение
					Ссылка = "";
				КонецПопытки;
				Если Не ПустаяСтрока(Ссылка) Тогда
					Прервать;
				КонецЕсли;
				ЭлементДокумента = ЭлементДокумента.parentElement;
			КонецЦикла;
		Исключение
			Ссылка = "";
		КонецПопытки;
	КонецЕсли;

	Если ПустаяСтрока(Ссылка) Тогда
		Возврат "";
	КонецЕсли;

	Позиция = Найти(НРег(Ссылка), "v8cmd:");
	Если Позиция = 0 Тогда
		Возврат "";
	КонецЕсли;

	Возврат Сред(Ссылка, Позиция + 6);

КонецФункции

&НаКлиенте
Процедура ВыполнитьКомандуДокумента(СтрокаКоманды)

	Части = СтрРазделить(СтрокаКоманды, ":", Ложь);
	Если Части.Количество() < 2 Тогда
		Возврат;
	КонецЕсли;

	Действие = НРег(СокрЛП(Части[0]));

	Индекс = 0;
	Попытка
		Индекс = Число(СокрЛП(СтрЗаменить(Части[1], "/", "")));
	Исключение
		Индекс = 0;
	КонецПопытки;

	Если Индекс = 0 Тогда
		Возврат;
	КонецЕсли;

	Если Действие = "run" Тогда
		ВыполнитьКодПоИндексу(Индекс);
	ИначеЕсли Действие = "reject" Тогда
		ОтклонитьКодСервер(Индекс);
	КонецЕсли;

КонецПроцедуры

&НаКлиенте
Процедура ВыполнитьКодПоИндексу(Индекс)

	Если Не РежимAct Тогда
		ПоказатьПредупреждение(, "Выполнение кода доступно только в режиме Act. Установите флажок ""Режим Act"".");
		Возврат;
	КонецЕсли;

	Если ВыполнятьНаСервере Тогда

		ВыполнитьКодСервер(Индекс);
		Возврат;
	КонецЕсли;

	Код = ПолучитьКодСервер(Индекс);
	Если ПустаяСтрока(Код) Тогда
		ПоказатьПредупреждение(, "Код с указанным номером не найден.");
		Возврат;
	КонецЕсли;

	Результат = "";
	Попытка
		Выполнить(Код);
		ТекстИтога = "Код выполнен на клиенте." + ?(ПустаяСтрока(Строка(Результат)), "", Символы.ПС + Строка(Результат));
		Успешно = Истина;
	Исключение
		ТекстИтога = "Ошибка выполнения на клиенте: " + ОписаниеОшибки();
		Успешно = Ложь;
	КонецПопытки;

	ЗафиксироватьИтогСервер(Индекс, ТекстИтога, Успешно);

КонецПроцедуры

#КонецОбласти

#Область СервернаяЛогика

&НаСервере
Процедура ОтправитьЗаданиеСервер(ТекстЗадания)

	ИнициализироватьНастройки();

	Обработка = РеквизитФормыВЗначение("Объект");

	ПоследнееЗадание = ТекстЗадания;

	// История диалога хранится БЕЗ системных сообщений: системный контекст (промпт, метаданные,
	// знания) собирается заново перед КАЖДЫМ запросом. Иначе, начиная со второго запроса,
	// модель переставала получать инструкции и "игнорировала" промпт.
	ИсторияДиалога = ЗагрузитьИсторию(Обработка);

	ОчищеннаяИстория = Новый Массив;
	Для Каждого СообщениеИстории Из ИсторияДиалога Цикл
		Если НРег(Строка(СообщениеИстории.Получить("role"))) <> "system" Тогда
			ОчищеннаяИстория.Добавить(СообщениеИстории);
		КонецЕсли;
	КонецЦикла;

	// Ограничиваем глубину истории, чтобы системный блок не вытеснялся из окна контекста модели.
	МаксимумСообщенийИстории = 20;
	Пока ОчищеннаяИстория.Количество() > МаксимумСообщенийИстории Цикл
		ОчищеннаяИстория.Удалить(0);
	КонецЦикла;

	Сообщения = Новый Массив;
	Сообщения.Добавить(Обработка.НовоеСообщение("system", Обработка.СистемныйПромптДляРежима(ЭтотОбъект.Объект.СистемныйПромпт, РежимAct)));


	ОбеспечитьКонтекстМетаданных(Обработка);

	Если Не ПустаяСтрока(КонтекстМетаданных) Тогда
		Сообщения.Добавить(Обработка.НовоеСообщение("system",
			"Контекст структуры текущей базы (реальные метаданные):" + Символы.ПС + КонтекстМетаданных));
	КонецЕсли;


	ТекстЗнаний = ПолучитьЗнанияДляКонтекста(Обработка);
	Если Не ПустаяСтрока(ТекстЗнаний) Тогда
		Сообщения.Добавить(Обработка.НовоеСообщение("system",
			"Накопленные знания по этой базе (из Git). Учитывай их обязательно:" + Символы.ПС + ТекстЗнаний));
	КонецЕсли;

	Для Каждого СообщениеИстории Из ОчищеннаяИстория Цикл
		Сообщения.Добавить(СообщениеИстории);
	КонецЦикла;

	// К заданию добавляется короткая памятка: правила в конце контекста соблюдаются моделями
	// заметно лучше, чем те же правила в начале системного промпта.
	Если РежимAct и СокрЛП(ТекстЗадания)="" Тогда
		Попытка
			ТекстЗадания=ИсторияДиалога[ИсторияДиалога.Количество()-1].Получить("content");
		Исключение КонецПопытки;
	КонецЕсли;	
	Сообщения.Добавить(Обработка.НовоеСообщение("user", Обработка.ПравилаДляЗадания() + ТекстЗадания));


	ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеПользователя(ТекстЗадания);

	Настройки = Новый Структура;
	Настройки.Вставить("АдресСервиса", ЭтотОбъект.Объект.АдресСервиса);
	Настройки.Вставить("Токен", ЭтотОбъект.Объект.Токен);
	Настройки.Вставить("Модель", ЭтотОбъект.Объект.Модель);
	Настройки.Вставить("ТаймаутСек", ЭтотОбъект.Объект.ТаймаутСек);
	Настройки.Вставить("МаксТокенов", ЭтотОбъект.Объект.МаксТокенов);

	ОтветСервиса = Обработка.ОтправитьЗапрос(Настройки, Сообщения);

	Если Не ОтветСервиса.Успех Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеОшибки(ОтветСервиса.Ошибка);
		ОбновитьПредставление(Обработка);
		Возврат;
	КонецЕсли;

	// Уроки, помеченные моделью маркером [ЗАПОМНИТЬ: ...], сохраняем в базу знаний.
	// Это позволяет накапливать знания из ЛЮБОГО сообщения диалога, а не только после
	// фактического выполнения кода.
	СохранитьЗаметкиИзОтвета(Обработка, ТекстЗадания, ОтветСервиса.Текст);

	// Маркер [ПЛАН ГОТОВ] - только подсказка оператору: флажок "Режим Act" он
	// устанавливает сам, обработка его программно не меняет.
	ПланГотов = (Не РежимAct) И Обработка.ЭтоПланГотов(ОтветСервиса.Текст);


	// Служебные маркеры оператору не показываем и в историю не пишем.
	ТекстОтвета = Обработка.УдалитьМаркерыЗаметок(ОтветСервиса.Текст);
	ТекстОтвета = СтрЗаменить(ТекстОтвета, Обработка.МаркерПланГотов(), "");
	ТекстОтвета = СокрП(ТекстОтвета);

	// В историю пишем "чистый" диалог: без системных сообщений и без памятки правил.
	ОчищеннаяИстория.Добавить(Обработка.НовоеСообщение("user", ТекстЗадания));
	ОчищеннаяИстория.Добавить(Обработка.НовоеСообщение("assistant", ТекстОтвета));
	СохранитьИсторию(Обработка, ОчищеннаяИстория);

	Коды = ЗагрузитьКоды(Обработка);
	Блоки = Обработка.РазобратьТекстНаБлоки(ТекстОтвета);

	БылИгнорированКод = Ложь;

	СодержимоеОтвета = "";
	Для Каждого Блок Из Блоки Цикл

		Если Блок.Вид = "код" И РежимAct Тогда

			ЗаписьКода = Новый Соответствие;
			ЗаписьКода.Вставить("code", Блок.Текст);
			ЗаписьКода.Вставить("lang", Блок.Язык);
			ЗаписьКода.Вставить("status", "новый");
			Коды.Добавить(ЗаписьКода);

			ИндексКода = Коды.Количество();
			ПоследнийИндексКода = ИндексКода;

			СодержимоеОтвета = СодержимоеОтвета + Обработка.HTMLБлокКода(ИндексКода, Блок.Текст, Блок.Язык);

		ИначеЕсли Блок.Вид = "код" Тогда
			// В режиме Plan код не регистрируется и не показывается фреймом с кнопками.
			БылИгнорированКод = Истина;

		Иначе
			СодержимоеОтвета = СодержимоеОтвета + Обработка.HTMLТекстОтвета(Блок.Текст);
		КонецЕсли;

	КонецЦикла;

	// Бейдж режима, в котором получен ответ.
	БейджРежима = ?(РежимAct, "ACT", "PLAN");
	СодержимоеОтвета = "<div class='text' style='color:#888888;font-size:10px;'>[режим: " + БейджРежима + "]</div>" + СодержимоеОтвета;

	ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLОберткаОтвета(СодержимоеОтвета);

	Если БылИгнорированКод Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
			"Режим Plan", "Агент прислал код, но в режиме Plan код не выполняется и не сохраняется."
			+ " Согласуйте план и переключитесь в режим Act (флажок ""Режим Act"").");
	КонецЕсли;

	СохранитьКоды(Обработка, Коды);

	// Подсказка оператору: план готов, пора вручную включить режим Act.
	Если ПланГотов Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
			"План готов", "Агент согласовал план. Установите флажок ""Режим Act"" - будет автоматически запрошен код по плану.");
	КонецЕсли;

	ОбновитьПредставление(Обработка);

КонецПроцедуры

// Серверная часть переключения флажка "Режим Act".
// При установке флажка автоматически отправляется запрос кода по согласованному плану;
// при снятии - возврат в режим планирования. Флажок меняется ТОЛЬКО оператором.
&НаСервере
Процедура РежимActПриИзмененииСервер()

	Обработка = РеквизитФормыВЗначение("Объект");

	Если РежимAct Тогда

		ИсторияДиалога = ЗагрузитьИсторию(Обработка);

		Если ИсторияДиалога.Количество() > 0 Тогда
			ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
				"Режим Act", "Включён режим исполнения. Запрашиваю у агента код по согласованному плану.");
			ОбновитьПредставление(Обработка);
			ОтправитьЗаданиеСервер("План согласован. Выдай код по этому плану одним блоком ```bsl.");
		Иначе
			ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
				"Режим Act", "Включён режим исполнения. Введите задание - агент выдаст код с кнопками подтверждения.");
			ОбновитьПредставление(Обработка);
		КонецЕсли;

	Иначе
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
			"Режим Plan", "Включён режим планирования: агент анализирует, задаёт вопросы и строит план. Код не выдаётся.");
		ОбновитьПредставление(Обработка);
	КонецЕсли;

КонецПроцедуры



&НаСервере
Процедура ВыполнитьКодСервер(Индекс)

	Обработка = РеквизитФормыВЗначение("Объект");

	Если Не РежимAct Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
			"Режим Plan", "Выполнение кода доступно только в режиме Act. Установите флажок ""Режим Act"".");
		ОбновитьПредставление(Обработка);
		Возврат;
	КонецЕсли;

	Коды = ЗагрузитьКоды(Обработка);

	Если Индекс < 1 Или Индекс > Коды.Количество() Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеОшибки("Код №" + Формат(Индекс, "ЧГ=0") + " не найден.");
		ОбновитьПредставление(Обработка);
		Возврат;
	КонецЕсли;

	ЭлементКода = Коды[Индекс - 1];
	Если Строка(ЭлементКода.Получить("status")) = "выполнен" Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
			"Код №" + Формат(Индекс, "ЧГ=0"), "Этот код уже был выполнен ранее.");
		ОбновитьПредставление(Обработка);
		Возврат;
	КонецЕсли;

	Код = Строка(ЭлементКода.Получить("code"));

	Результат = "";
	Попытка
		Выполнить(Код);
		ТекстИтога = "Код выполнен на сервере." + ?(ПустаяСтрока(Строка(Результат)), "", Символы.ПС + Строка(Результат));
		Успешно = Истина;
	Исключение
		ТекстИтога = "Ошибка выполнения на сервере: " + ПодробноеПредставлениеОшибки(ИнформацияОбОшибке());
		Успешно = Ложь;
	КонецПопытки;

	ЭлементКода.Вставить("status", ?(Успешно, "выполнен", "ошибка"));
	СохранитьКоды(Обработка, Коды);

	ЗарегистрироватьИтог(Обработка, Индекс, ТекстИтога, Успешно);
	ОбновитьПредставление(Обработка);

КонецПроцедуры

&НаСервере
Функция ПолучитьКодСервер(Индекс)

	Обработка = РеквизитФормыВЗначение("Объект");
	Коды = ЗагрузитьКоды(Обработка);

	Если Индекс < 1 Или Индекс > Коды.Количество() Тогда
		Возврат "";
	КонецЕсли;

	Возврат Строка(Коды[Индекс - 1].Получить("code"));

КонецФункции

&НаСервере
Процедура ЗафиксироватьИтогСервер(Индекс, ТекстИтога, Успешно)

	Обработка = РеквизитФормыВЗначение("Объект");

	Коды = ЗагрузитьКоды(Обработка);
	Если Индекс >= 1 И Индекс <= Коды.Количество() Тогда
		Коды[Индекс - 1].Вставить("status", ?(Успешно, "выполнен", "ошибка"));
		СохранитьКоды(Обработка, Коды);
	КонецЕсли;

	ЗарегистрироватьИтог(Обработка, Индекс, ТекстИтога, Успешно);
	ОбновитьПредставление(Обработка);

КонецПроцедуры

&НаСервере
Процедура ОтклонитьКодСервер(Индекс)

	Обработка = РеквизитФормыВЗначение("Объект");

	Коды = ЗагрузитьКоды(Обработка);
	Если Индекс >= 1 И Индекс <= Коды.Количество() Тогда
		Коды[Индекс - 1].Вставить("status", "отклонен");
		СохранитьКоды(Обработка, Коды);
	КонецЕсли;

	ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
		"Код №" + Формат(Индекс, "ЧГ=0"), "Код отклонён пользователем и не выполнялся.");

	// Сообщаем агенту об отклонении, чтобы он мог предложить другой вариант.
	Сообщения = ЗагрузитьИсторию(Обработка);
	Если Сообщения.Количество() > 0 Тогда
		Сообщения.Добавить(Обработка.НовоеСообщение("user",
			"Пользователь отклонил предложенный код №" + Формат(Индекс, "ЧГ=0") + ". Предложи другой вариант решения или задай уточняющий вопрос."));
		СохранитьИсторию(Обработка, Сообщения);
	КонецЕсли;

	ОбновитьПредставление(Обработка);

КонецПроцедуры

&НаСервере
Процедура ОчиститьДиалогСервер()

	Обработка = РеквизитФормыВЗначение("Объект");

	ТелоДиалогаHTML = "";
	ИсторияJSON = "";
	КодыJSON = "";
	ПоследнийИндексКода = 0;

	ОбновитьПредставление(Обработка);

КонецПроцедуры

// Подключается к временной ИБ через COM, загружает в неё структуру конфигурации
// из КаталогСтруктурыВременнойБазыДанных и сохраняет описание метаданных как контекст для ИИ.
&НаСервере
Процедура ПодключитьВременнуюИБСервер()

	Обработка = РеквизитФормыВЗначение("Объект");

	РезультатПодключения = Обработка.ПодключитьВременнуюИБ(
		ЭтотОбъект.Объект.СтрокаПодключенияВременнойИБ, ЭтотОбъект.Объект.ПользовательВременнойИБ, ЭтотОбъект.Объект.ПарольПользователяВременнойИБ);

	Если Не РезультатПодключения.Успех Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеОшибки(
			"Не удалось подключиться к временной ИБ: " + РезультатПодключения.Ошибка);
		ОбновитьПредставление(Обработка);
		Возврат;
	КонецЕсли;

	Если Не ПустаяСтрока(ЭтотОбъект.Объект.КаталогСтруктурыВременнойБазыДанных) Тогда
		РезультатЗагрузки = Обработка.ЗагрузитьСтруктуруКонфигурации(
			РезультатПодключения.Приложение, ЭтотОбъект.Объект.КаталогСтруктурыВременнойБазыДанных);
		Если Не РезультатЗагрузки.Успех Тогда
			ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеОшибки(
				"Не удалось загрузить структуру конфигурации во временную ИБ: " + РезультатЗагрузки.Ошибка);
			ОбновитьПредставление(Обработка);
			Возврат;
		КонецЕсли;
	КонецЕсли;

	КонтекстМетаданных = Обработка.ПолучитьОписаниеМетаданных(РезультатПодключения.Приложение);

	ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
		"Временная ИБ",
		"Подключение установлено. Структура метаданных получена и будет использоваться"
		+ " как контекст реальной структуры базы для ИИ-агента.");

	ОбновитьПредставление(Обработка);

КонецПроцедуры

// Выгружает структуру конфигурации ТЕКУЩЕЙ базы (в которой запущена сама обработка) в XML-файлы.
// ВАЖНО: COM-соединение здесь НЕ используется и НЕ требуется - это не временная ИБ, а база,
// в которой мы уже находимся и выполняем этот самый код.
&НаСервере
Процедура ВыгрузитьСтруктуруТекущейИБСервер()

	Обработка = РеквизитФормыВЗначение("Объект");

	Результат = Обработка.ВыгрузитьСтруктуруТекущейБазы(ЭтотОбъект.Объект.КаталогСтруктурыТекущейБазы);

	Если Результат.Успех Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(
			"Текущая база",
			"Структура текущей конфигурации выгружена в каталог: " + ЭтотОбъект.Объект.КаталогСтруктурыТекущейБазы);
	Иначе
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеОшибки(
			"Не удалось выгрузить структуру текущей базы: " + Результат.Ошибка);
	КонецЕсли;

	ОбновитьПредставление(Обработка);

КонецПроцедуры

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

// Обработчик события формы OnCreateAtServer. Автоматически заполняет реквизит ТекущаяБаза
// строкой соединения БАЗЫ, В КОТОРОЙ ЗАПУЩЕНА САМА ОБРАБОТКА (без COM - это просто чтение
// параметров текущего сеанса, а не подключение к какой-либо внешней базе).
&НаСервере
Процедура ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	Обработка = РеквизитФормыВЗначение("Объект");

	Если ПустаяСтрока(ЭтотОбъект.Объект.ТекущаяБаза) Тогда
		Попытка
			ТекущаяБаза = Обработка.ПолучитьСтрокуПодключенияТекущейБазы();
		Исключение
			ТекущаяБаза = "";
		КонецПопытки;
	КонецЕсли;

	// Контекст метаданных для LLM и отпечатка Git - из текущей базы, без COM.
	ОбеспечитьКонтекстМетаданных(Обработка);

	// Автоматический стартовый запрос для изучения базы знаний при открытии формы.
	ОтправитьСтартовыйЗапросСервер();

КонецПроцедуры

// Автоматически отправляет агенту стартовый запрос для изучения накопленных знаний.
// Вызывается один раз при открытии формы, чтобы агент проанализировал базу знаний
// и подготовил контекст для генерации корректного кода.
&НаСервере
Процедура ОтправитьСтартовыйЗапросСервер()

	Если СтартовыйЗапросОтправлен Тогда
		Возврат;
	КонецЕсли;

	// Проверяем, настроен ли Git для загрузки знаний
	Если ПустаяСтрока(ЭтотОбъект.Объект.РепозиторийGit) Тогда
		Возврат;
	КонецЕсли;

	ИнициализироватьНастройки();

	Обработка = РеквизитФормыВЗначение("Объект");

	// Загружаем знания из Git
	ОбеспечитьКонтекстМетаданных(Обработка);
	ТекстЗнаний = ПолучитьЗнанияДляКонтекста(Обработка);

	Если ПустаяСтрока(ТекстЗнаний) Тогда
		СтартовыйЗапросОтправлен = Истина;
		Возврат;
	КонецЕсли;

	// Формируем стартовый запрос для агента
	ТекстЗадания = "[СИСТЕМНАЯ ИНИЦИАЛИЗАЦИЯ] Ты - ИИ-агент 1С 8.3, внедренный в объект - обработка 'ExtCntrl', "
		+ "в КОНТЕКСТ ФОРМЫ ЭТОГО ОБЪЕКТА, ты можешь генерировать код и исполняеть его методом Выполнить()"
		+ " используя встроенный язык bsl, объекты и свойства системы 1С:Предриятие 8.3.";

	// Отправляем запрос через существующий механизм
	ПоследнееЗадание = ТекстЗадания;

	Сообщения = Новый Массив;
	Сообщения.Добавить(Обработка.НовоеСообщение("system", Обработка.СистемныйПромптДляРежима(ЭтотОбъект.Объект.СистемныйПромпт, РежимAct)));

	Если Не ПустаяСтрока(КонтекстМетаданных) Тогда
		Сообщения.Добавить(Обработка.НовоеСообщение("system",
			"Контекст структуры текущей базы (реальные метаданные):" + Символы.ПС + КонтекстМетаданных));
	КонецЕсли;

	Сообщения.Добавить(Обработка.НовоеСообщение("system",
		"Накопленные знания по этой базе (из Git). Учитывай их обязательно:" + Символы.ПС + ТекстЗнаний));

	Сообщения.Добавить(Обработка.НовоеСообщение("user", Обработка.ПравилаДляЗадания() + ТекстЗадания));

	ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеПользователя(ТекстЗадания);

	Настройки = Новый Структура;
	Настройки.Вставить("АдресСервиса", ЭтотОбъект.Объект.АдресСервиса);
	Настройки.Вставить("Токен", ЭтотОбъект.Объект.Токен);
	Настройки.Вставить("Модель", ЭтотОбъект.Объект.Модель);
	Настройки.Вставить("ТаймаутСек", ЭтотОбъект.Объект.ТаймаутСек);
	Настройки.Вставить("МаксТокенов", ЭтотОбъект.Объект.МаксТокенов);

	ОтветСервиса = Обработка.ОтправитьЗапрос(Настройки, Сообщения);

	Если Не ОтветСервиса.Успех Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеОшибки(ОтветСервиса.Ошибка);
		ОбновитьПредставление(Обработка);
		СтартовыйЗапросОтправлен = Истина;
		Возврат;
	КонецЕсли;

	// Сохраняем ответ агента в историю
	Сообщения.Добавить(Обработка.НовоеСообщение("assistant", ОтветСервиса.Текст));
	СохранитьИсторию(Обработка, Сообщения);

	// Отображаем ответ
	ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLОберткаОтвета(Обработка.HTMLТекстОтвета(ОтветСервиса.Текст));

	СтартовыйЗапросОтправлен = Истина;

	ОбновитьПредставление(Обработка);

КонецПроцедуры

// Заполняет КонтекстМетаданных описанием ТЕКУЩЕЙ базы, если он ещё пуст.
// COM и временная ИБ для этого не нужны: метаданные доступны в текущем сеансе.
// Если оператор ранее подключил временную ИБ - её контекст не перезаписываем.
&НаСервере
Процедура ОбеспечитьКонтекстМетаданных(Обработка)

	Если Не ПустаяСтрока(КонтекстМетаданных) Тогда
		Возврат;
	КонецЕсли;

	Попытка
		КонтекстМетаданных = Обработка.ПолучитьОписаниеМетаданныхТекущейБазы();
	Исключение
		КонтекстМетаданных = "";
	КонецПопытки;

КонецПроцедуры


&НаСервере
Процедура ИнициализироватьНастройки()

	Обработка = РеквизитФормыВЗначение("Объект");

	Если ПустаяСтрока(ЭтотОбъект.Объект.АдресСервиса) Тогда
		АдресСервиса = Обработка.АдресСервисаПоУмолчанию();
	КонецЕсли;

	Если ПустаяСтрока(ЭтотОбъект.Объект.Модель) Тогда
		Модель = Обработка.МодельПоУмолчанию();
	КонецЕсли;

	Если ПустаяСтрока(ЭтотОбъект.Объект.СистемныйПромпт) Тогда
		СистемныйПромпт = Обработка.СистемныйПромптПоУмолчанию();
	КонецЕсли;

	Если Не ЗначениеЗаполнено(ЭтотОбъект.Объект.ТаймаутСек) Тогда
		ТаймаутСек = Обработка.ТаймаутПоУмолчанию();
	КонецЕсли;

	Если Не ЗначениеЗаполнено(ЭтотОбъект.Объект.МаксТокенов) Тогда
		МаксТокенов = Обработка.МаксТокеновПоУмолчанию();
	КонецЕсли;

КонецПроцедуры

&НаСервере
Процедура ОбновитьПредставление(Обработка)

	Процесс = Обработка.СобратьДокумент(ТелоДиалогаHTML);

КонецПроцедуры

&НаСервере
Процедура ЗарегистрироватьИтог(Обработка, Индекс, ТекстИтога, Успешно)

	Заголовок = "Результат выполнения кода №" + Формат(Индекс, "ЧГ=0");

	Если Успешно Тогда
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеСлужебное(Заголовок, ТекстИтога);
	Иначе
		ТелоДиалогаHTML = ТелоДиалогаHTML + Обработка.HTMLСообщениеОшибки(Заголовок + Символы.ПС + ТекстИтога);
	КонецЕсли;

	// Передаём агенту итог выполнения, чтобы он учитывал его в следующих шагах.
	Сообщения = ЗагрузитьИсторию(Обработка);
	Если Сообщения.Количество() > 0 Тогда
		Сообщения.Добавить(Обработка.НовоеСообщение("user", Заголовок + ":" + Символы.ПС + ТекстИтога));
		СохранитьИсторию(Обработка, Сообщения);
	КонецЕсли;

	СохранитьЗнаниеПослеВыполнения(Обработка, Индекс, ТекстИтога, Успешно);

КонецПроцедуры

// Собирает структуру настроек для обращения к базе знаний Git.
&НаСервере
Функция СобратьНастройкиGit()

	Настройки = Новый Структура;
	Настройки.Вставить("АдресGitAPI", ЭтотОбъект.Объект.АдресGitAPI);
	Настройки.Вставить("РепозиторийGit", ЭтотОбъект.Объект.РепозиторийGit);
	Настройки.Вставить("ВеткаGit", ЭтотОбъект.Объект.ВеткаGit);
	Настройки.Вставить("ТокенGit", ЭтотОбъект.Объект.ТокенGit);
	Настройки.Вставить("КаталогБазыЗнанийGit", ЭтотОбъект.Объект.КаталогБазыЗнанийGit);

	Возврат Настройки;

КонецФункции

// Загружает накопленные знания по прошлым решениям для текущей конфигурации (по отпечатку
// её метаданных) из репозитория Git, чтобы подмешать их в системный промпт перед запросом к LLM.
&НаСервере
Функция ПолучитьЗнанияДляКонтекста(Обработка)

	Если ПустаяСтрока(ЭтотОбъект.Объект.РепозиторийGit) Тогда
		Возврат "";
	КонецЕсли;

	ОбеспечитьКонтекстМетаданных(Обработка);
	Если ПустаяСтрока(КонтекстМетаданных) Тогда
		Возврат "";
	КонецЕсли;

	Отпечаток = Обработка.ВычислитьОтпечаток(КонтекстМетаданных);

	Если ПустаяСтрока(Отпечаток) Тогда
		Возврат "";
	КонецЕсли;

	Попытка
		Возврат Обработка.ЗагрузитьЗнания(СобратьНастройкиGit(), Отпечаток, 10);

	Исключение
		Возврат "";
	КонецПопытки;

КонецФункции

// Сохраняет запись о выполненном коде в базу знаний Git (если она настроена и известен
// отпечаток текущей конфигурации). Ошибки сохранения не должны прерывать основной сценарий.
&НаСервере
Процедура СохранитьЗнаниеПослеВыполнения(Обработка, Индекс, ТекстИтога, Успешно)

	Если ПустаяСтрока(ЭтотОбъект.Объект.РепозиторийGit) Тогда
		Возврат;
	КонецЕсли;

	Код = ПолучитьКодСервер(Индекс);
	Если ПустаяСтрока(Код) Тогда
		Возврат;
	КонецЕсли;

	ОбеспечитьКонтекстМетаданных(Обработка);
	Отпечаток = Обработка.ВычислитьОтпечаток(КонтекстМетаданных);

	Если ПустаяСтрока(Отпечаток) Тогда
		Возврат;
	КонецЕсли;

	Попытка
		Обработка.СохранитьЗнание(СобратьНастройкиGit(), Отпечаток, ПоследнееЗадание, Код, "bsl", ТекстИтога, Успешно, "code");
	Исключение
		// Ошибки сохранения знаний не критичны и не должны мешать основному диалогу.
		ТекстОшибкиЗнаний = ОписаниеОшибки();
	КонецПопытки;

КонецПроцедуры

// Сохраняет в базу знаний уроки, которые агент пометил маркером [ЗАПОМНИТЬ: ...].
// В отличие от СохранитьЗнаниеПослеВыполнения, знания копятся из ЛЮБОГО сообщения диалога:
// уточнений оператора, признанных ошибок, выбранного направления решения.
&НаСервере
Процедура СохранитьЗаметкиИзОтвета(Обработка, ТекстЗадания, ТекстОтветаМодели)

	Если ПустаяСтрока(ЭтотОбъект.Объект.РепозиторийGit) Тогда
		Возврат;
	КонецЕсли;

	Заметки = Обработка.ИзвлечьЗаметки(ТекстОтветаМодели);
	Если Заметки.Количество() = 0 Тогда
		Возврат;
	КонецЕсли;

	ОбеспечитьКонтекстМетаданных(Обработка);
	Отпечаток = Обработка.ВычислитьОтпечаток(КонтекстМетаданных);

	Если ПустаяСтрока(Отпечаток) Тогда
		Возврат;
	КонецЕсли;

	НастройкиGit = СобратьНастройкиGit();

	Для Каждого Заметка Из Заметки Цикл
		Попытка
			Обработка.СохранитьЗнание(НастройкиGit, Отпечаток, ТекстЗадания, "", "", Заметка, Истина, "note");
		Исключение
			// Ошибки сохранения знаний не критичны и не должны мешать основному диалогу.
			ТекстОшибкиЗнаний = ОписаниеОшибки();
		КонецПопытки;
	КонецЦикла;

КонецПроцедуры


&НаСервере
Функция ЗагрузитьИсторию(Обработка)

	Если ПустаяСтрока(ИсторияJSON) Тогда
		Возврат Новый Массив;
	КонецЕсли;

	Попытка
		Данные = Обработка.JSONВОбъект(ИсторияJSON);
	Исключение
		Данные = Неопределено;
	КонецПопытки;

	Если ТипЗнч(Данные) <> Тип("Массив") Тогда
		Возврат Новый Массив;
	КонецЕсли;

	Возврат Данные;

КонецФункции

&НаСервере
Процедура СохранитьИсторию(Обработка, Сообщения)

	ИсторияJSON = Обработка.ОбъектВJSON(Сообщения);

КонецПроцедуры

&НаСервере
Функция ЗагрузитьКоды(Обработка)

	Если ПустаяСтрока(КодыJSON) Тогда
		Возврат Новый Массив;
	КонецЕсли;

	Попытка
		Данные = Обработка.JSONВОбъект(КодыJSON);
	Исключение
		Данные = Неопределено;
	КонецПопытки;

	Если ТипЗнч(Данные) <> Тип("Массив") Тогда
		Возврат Новый Массив;
	КонецЕсли;

	Возврат Данные;

КонецФункции

&НаСервере
Процедура СохранитьКоды(Обработка, Коды)

	КодыJSON = Обработка.ОбъектВJSON(Коды);

КонецПроцедуры

#КонецОбласти


